package com.devtunasoft.tuneros.qa55

import java.io.File
import java.security.MessageDigest

/**
 * QA-55 framework-free contract: bounded XMLTV category/genre token admission.
 *
 * The registry admits a canonical token only after trim, ASCII upper-casing and a bounded
 * synonym map. Unknown, empty, control-bearing and oversized tokens fail closed. The same
 * source is compiled into the host gate and into the instrumented mirror, so both digest
 * the same generated bytes. No URLs, credentials, PINs or recording payloads are used.
 */
object Qa55Contract {
    val TAB: Char = 9.toChar()
    val NL: Char = 10.toChar()
    const val SEED: Long = 20261124L

    const val MAX_TOKEN_CHARS = 24
    const val MAX_TOKENS_PER_PROGRAMME = 4
    const val CHANNEL_COUNT = 48
    const val PROGRAMME_COUNT = 120
    const val CORRUPT_COUNT = 9

    val REGISTRY = arrayOf("NEWS", "SPORTS", "MOVIE", "KIDS", "DOC", "MUSIC")
    val REGISTRY_SET = REGISTRY.toSet()

    val SYNONYMS = mapOf(
        "SPORT" to "SPORTS",
        "FILM" to "MOVIE",
        "CHILDREN" to "KIDS",
        "DOCUMENTARY" to "DOC",
        "MUSICAL" to "MUSIC",
    )

    val CASE_HEADER = "id" + TAB + "raw" + TAB + "canonical" + TAB + "decision" + TAB + "code"
    val DIM_HEADER = "key" + TAB + "value"
    val CORRUPT_HEADER = "id" + TAB + "family" + TAB + "bytes"
    val REPORT_HEADER = "# qa55 diagnostics carry check ids, counts and digests only"

    val DATA_FILES = arrayOf("dimensions.tsv", "cases.tsv", "corrupt.txt", "guide.xmltv", "report-copy.txt")

    data class Case(
        val id: String, val raw: String, val canonical: String,
        val decision: String, val code: String,
    )

    data class Programme(
        val channel: String, val title: String, val desc: String,
        val rawTokens: List<String>,
    )

    data class Parsed(
        val dimensions: Map<String, String>,
        val cases: List<Case>,
        val corrupt: Map<String, Pair<String, ByteArray>>,
        val programmes: List<Programme>,
        val guideBytes: ByteArray,
        val files: Map<String, ByteArray>,
    )

    fun sha256(bytes: ByteArray): String {
        val digest = MessageDigest.getInstance("SHA-256").digest(bytes)
        val chars = "0123456789abcdef".toCharArray()
        val out = StringBuilder(digest.size * 2)
        for (b in digest) {
            val v = (b.toInt() and 0xFF)
            out.append(chars[v ushr 4]).append(chars[v and 0x0F])
        }
        return out.toString()
    }

    fun derivedToken(): String {
        val mix = (SEED * 6364136223846793005L + 1442695040888963407L) and Long.MAX_VALUE
        return "qa55mk" + java.lang.Long.toHexString(mix).padStart(16, '0')
    }

    fun normalize(raw: String): String {
        val trimmed = raw.trim()
        if (trimmed.isEmpty()) return ""
        for (ch in trimmed) if (ch.code < 0x20 || ch.code == 0x7F) return ""
        val upper = trimmed.uppercase()
        val mapped = SYNONYMS[upper] ?: upper
        if (mapped.length > MAX_TOKEN_CHARS) return ""
        return if (mapped in REGISTRY_SET) mapped else ""
    }

    private fun rows(text: String): List<String> =
        text.split(NL).dropLastWhile { it.isEmpty() }

    private fun strictFields(line: String, expected: Int): List<String>? {
        val fields = line.split(TAB, limit = expected + 1)
        return if (fields.size == expected) fields else null
    }

    fun buildCases(): List<Case> {
        val out = ArrayList<Case>()
        fun add(id: String, raw: String, canonical: String, decision: String, code: String) {
            out.add(Case(id, raw, canonical, decision, code))
        }
        add("C00", "NEWS", "NEWS", "ADMIT", "ADMIT")
        add("C01", "sports", "SPORTS", "ADMIT", "ADMIT")
        add("C02", "  movie  ", "MOVIE", "ADMIT", "ADMIT")
        add("C03", "SPORT", "SPORTS", "ADMIT", "ADMIT")
        add("C04", "film", "MOVIE", "ADMIT", "ADMIT")
        add("C05", "children", "KIDS", "ADMIT", "ADMIT")
        add("C06", "DOCUMENTARY", "DOC", "ADMIT", "ADMIT")
        add("C07", "musical", "MUSIC", "ADMIT", "ADMIT")
        add("C08", "  Kids  ", "KIDS", "ADMIT", "ADMIT")
        add("C09", "mUsIc", "MUSIC", "ADMIT", "ADMIT")
        add("C10", "NEWS", "NEWS", "ADMIT", "ADMIT")
        add("C11", "UNLISTED", "-", "REJECT", "REJECT_UNKNOWN")
        add("C12", "", "-", "REJECT", "REJECT_EMPTY")
        add("C13", "    ", "-", "REJECT", "REJECT_EMPTY")
        add("C14", "ABCDEFGHIJKLMNOPQRSTUVWXY", "-", "REJECT", "REJECT_LENGTH")
        add("C15", "NEW" + 1.toChar() + "S", "-", "REJECT", "REJECT_CONTROL")
        add("C16", "SPORTS2", "-", "REJECT", "REJECT_UNKNOWN")
        add("C17", "documentary", "DOC", "ADMIT", "ADMIT")
        return out
    }

    private fun canonicalDoc(): String {
        val sb = StringBuilder()
        sb.append("<!DOCTYPE tv SYSTEM \"xmltv.dtd\">").append(NL)
        sb.append("<tv>").append(NL)
        sb.append("<channel id=\"c0001\"><display-name>Name-0001</display-name></channel>").append(NL)
        sb.append("<programme channel=\"c0001\" start=\"20260222000000 +0000\" stop=\"20260222010000 +0000\">").append(NL)
        sb.append("<title>Title-0001</title>").append(NL)
        sb.append("<desc>Desc-0001</desc>").append(NL)
        sb.append("<category>NEWS</category>").append(NL)
        sb.append("</programme>").append(NL)
        sb.append("</tv>").append(NL)
        return sb.toString()
    }

    private fun hex(bytes: ByteArray): String {
        val chars = "0123456789abcdef".toCharArray()
        val out = StringBuilder(bytes.size * 2)
        for (b in bytes) {
            val v = b.toInt() and 0xFF
            out.append(chars[v ushr 4]).append(chars[v and 0x0F])
        }
        return out.toString()
    }

    private fun unhex(value: String): ByteArray {
        val out = ByteArray(value.length / 2)
        var i = 0
        while (i < out.size) {
            out[i] = ((Character.digit(value[i * 2], 16) shl 4) or
                Character.digit(value[i * 2 + 1], 16)).toByte()
            i++
        }
        return out
    }

    fun buildCorrupt(): Map<String, Pair<String, ByteArray>> {
        val canonical = canonicalDoc()
        val out = LinkedHashMap<String, Pair<String, ByteArray>>()
        fun add(id: String, family: String, text: String) {
            out[id] = Pair(family, text.toByteArray(Charsets.UTF_8))
        }
        add("X01", "PROLOG", canonical.replace("xmltv.dtd", "other.dtd"))
        add("X02", "PROLOG", canonical.replace(
            "<!DOCTYPE tv SYSTEM \"xmltv.dtd\">",
            "<!DOCTYPE tv SYSTEM \"xmltv.dtd\" [<!ENTITY x \"y\">]>"))
        add("X03", "PROLOG", canonical.replace("<tv>", "<guide>"))
        add("X04", "PROLOG", canonical.replace("<category>NEWS</category>", "<category>NEWS"))
        val badUtf8 = canonical.toByteArray(Charsets.UTF_8)
        badUtf8[canonical.indexOf("Title-0001")] = 0xFF.toByte()
        out["X05"] = Pair("PROLOG", badUtf8)
        add("X06", "PROLOG", "<!DOCTYPE tv SYSTEM \"xmltv.dtd\">" + NL +
            "<!DOCTYPE tv SYSTEM \"xmltv.dtd\">" + canonical.substringAfter(NL))
        val padding = StringBuilder("<!--")
        for (i in 0 until 9000) padding.append('A')
        padding.append("-->").append(NL)
        add("X07", "PROLOG", padding.toString() + canonical)
        val deep = StringBuilder()
        deep.append("<!DOCTYPE tv SYSTEM \"xmltv.dtd\">").append(NL)
        deep.append("<tv>").append(NL)
        deep.append("<channel id=\"c0001\"><display-name>Name-0001</display-name></channel>").append(NL)
        deep.append("<programme channel=\"c0001\" start=\"20260222000000 +0000\" stop=\"20260222010000 +0000\">").append(NL)
        deep.append("<title>Title-0001</title>").append(NL)
        for (i in 0 until 70) deep.append("<category>NEWS")
        deep.append("BODY")
        for (i in 0 until 70) deep.append("</category>")
        deep.append(NL).append("</programme>").append(NL).append("</tv>").append(NL)
        add("X08", "PROLOG", deep.toString())
        // Token-family corrupt input stays in cases.tsv; this document is well-formed but
        // carries a category token far beyond the admission bound. It must never become
        // programme metadata, and is used only as a no-false-admission control.
        add("X09", "TOKEN_ONLY", canonical.replace("NEWS</category>",
            "ABCDEFGHIJKLMNOPQRSTUVWXY</category>"))
        return out
    }

    fun buildGuide(): ByteArray {
        val cases = buildCases().filter { it.decision == "ADMIT" }
        val sb = StringBuilder()
        sb.append("<!DOCTYPE tv SYSTEM \"xmltv.dtd\">").append(NL)
        sb.append("<tv>").append(NL)
        for (i in 0 until CHANNEL_COUNT) {
            val id = "c" + (i + 1).toString().padStart(5, '0')
            val name = "Name-" + (i + 1).toString().padStart(5, '0')
            sb.append("<channel id=\"").append(id).append("\"><display-name>")
                .append(name).append("</display-name></channel>").append(NL)
        }
        for (i in 0 until PROGRAMME_COUNT) {
            val id = (i + 1).toString().padStart(5, '0')
            val channel = "c" + (i % CHANNEL_COUNT + 1).toString().padStart(5, '0')
            sb.append("<programme channel=\"").append(channel)
                .append("\" start=\"20260222000000 +0000\" stop=\"20260222010000 +0000\">").append(NL)
            if (i == PROGRAMME_COUNT - 1) {
                sb.append("<title>   </title>").append(NL)
            } else if (i == PROGRAMME_COUNT - 2) {
                val long = "X".repeat(300)
                sb.append("<title>").append(long).append("</title>").append(NL)
            } else {
                sb.append("<title>  Title-").append(id).append("  </title>").append(NL)
            }
            sb.append("<desc>  Desc-").append(id).append("  </desc>").append(NL)
            val count = 1 + (i % MAX_TOKENS_PER_PROGRAMME)
            for (k in 0 until count) {
                val token = cases[(i + k) % cases.size]
                val tag = if ((i + k) % 2 == 0) "category" else "genre"
                val raw = if (i % 7 == 0 && k == 0) "    " + token.raw + "  " else token.raw
                sb.append("<").append(tag).append(">").append(raw)
                    .append("</").append(tag).append(">").append(NL)
            }
            if (i % 11 == 0) sb.append("<genre>UNLISTED</genre>").append(NL)
            sb.append("</programme>").append(NL)
        }
        sb.append("</tv>").append(NL)
        return sb.toString().toByteArray(Charsets.UTF_8)
    }

    fun generate(): Map<String, ByteArray> {
        val out = LinkedHashMap<String, ByteArray>()
        fun add(name: String, text: String) { out[name] = text.toByteArray(Charsets.UTF_8) }

        val cases = buildCases()
        val corrupt = buildCorrupt()
        val guide = buildGuide()

        val caseLines = ArrayList<String>()
        caseLines.add(CASE_HEADER)
        for (c in cases) caseLines.add(
            c.id + TAB + c.raw + TAB + c.canonical + TAB + c.decision + TAB + c.code)
        add("cases.tsv", caseLines.joinToString(NL.toString()) + NL)

        val corruptLines = ArrayList<String>()
        corruptLines.add(CORRUPT_HEADER)
        for ((id, value) in corrupt) corruptLines.add(
            id + TAB + value.first + TAB + hex(value.second))
        add("corrupt.txt", corruptLines.joinToString(NL.toString()) + NL)

        add("guide.xmltv", guide.toString(Charsets.UTF_8))

        val admitted = LinkedHashMap<String, ArrayList<String>>()
        for ((raw, canonical) in parseProgrammeTokens(guide.toString(Charsets.UTF_8))) {
            admitted.getOrPut(raw) { ArrayList() }.add(canonical)
        }
        val mirror = StringBuilder()
        for ((raw, canonicals) in admitted) {
            mirror.append(raw).append('=')
            canonicals.distinct().sorted().joinTo(mirror, ",")
            mirror.append(';')
        }
        val mirrorDigest = sha256(mirror.toString().toByteArray(Charsets.UTF_8))

        val dimensions = ArrayList<String>()
        dimensions.add(DIM_HEADER)
        dimensions.add("registry_count" + TAB + REGISTRY.size)
        dimensions.add("case_count" + TAB + cases.size)
        dimensions.add("channel_count" + TAB + CHANNEL_COUNT)
        dimensions.add("programme_count" + TAB + PROGRAMME_COUNT)
        dimensions.add("max_tokens" + TAB + MAX_TOKENS_PER_PROGRAMME)
        dimensions.add("corrupt_count" + TAB + corrupt.size)
        dimensions.add("guide_sha256" + TAB + sha256(guide))
        dimensions.add("mirror_digest" + TAB + mirrorDigest)
        add("dimensions.tsv", dimensions.joinToString(NL.toString()) + NL)

        val report = ArrayList<String>()
        report.add(REPORT_HEADER)
        report.add("CHECK" + TAB + "TOKEN_NORMALIZATION" + TAB + "PASS" + TAB + "count=" + cases.size)
        report.add("CHECK" + TAB + "CORRUPT_FAIL_CLOSED" + TAB + "PASS" + TAB + "count=" + corrupt.size)
        report.add("CHECK" + TAB + "PRIVACY_SCAN" + TAB + "PASS" + TAB + "hits=0")
        add("report-copy.txt", report.joinToString(NL.toString()) + NL)

        val manifest = StringBuilder()
        for (name in DATA_FILES) manifest.append(sha256(out.getValue(name))).append(TAB).append(name).append(NL)
        out["sha256.txt"] = manifest.toString().toByteArray(Charsets.UTF_8)
        return out
    }

    /** Derives (channel, canonical token set) pairs from parsed fixture bytes, not the builder. */
    fun parseProgrammeTokens(text: String): List<Pair<String, String>> {
        val out = ArrayList<Pair<String, String>>()
        var currentChannel = ""
        for (line in rows(text)) {
            when {
                line.startsWith("<programme ") -> currentChannel = line.substringAfter("channel=\"")
                    .substringBefore("\"")
                line.startsWith("<category>") || line.startsWith("<genre>") -> {
                    val raw = line.substringAfter('>').substringBefore('<')
                    out.add(Pair(currentChannel, normalize(raw)))
                }
            }
        }
        return out
    }

    fun parseFixture(files: Map<String, ByteArray>): Parsed? {
        val dimText = files["dimensions.tsv"]?.toString(Charsets.UTF_8) ?: return null
        val caseText = files["cases.tsv"]?.toString(Charsets.UTF_8) ?: return null
        val corruptText = files["corrupt.txt"]?.toString(Charsets.UTF_8) ?: return null
        val guideBytes = files["guide.xmltv"] ?: return null
        val guideText = guideBytes.toString(Charsets.UTF_8)

        val dimensions = LinkedHashMap<String, String>()
        for (line in rows(dimText).drop(1)) {
            val f = strictFields(line, 2) ?: return null
            dimensions[f[0]] = f[1]
        }
        val cases = ArrayList<Case>()
        for (line in rows(caseText).drop(1)) {
            val f = strictFields(line, 5) ?: return null
            cases.add(Case(f[0], f[1], f[2], f[3], f[4]))
        }
        val corrupt = LinkedHashMap<String, Pair<String, ByteArray>>()
        for (line in rows(corruptText).drop(1)) {
            val f = strictFields(line, 3) ?: return null
            corrupt[f[0]] = Pair(f[1], unhex(f[2]))
        }
        val programmes = ArrayList<Programme>()
        var curChannel = ""
        var curTitle = ""
        var curDesc = ""
        val curTokens = ArrayList<String>()
        fun finish() {
            if (curChannel.isNotEmpty()) programmes.add(
                Programme(curChannel, curTitle, curDesc, ArrayList(curTokens)))
            curChannel = ""; curTitle = ""; curDesc = ""; curTokens.clear()
        }
        for (line in rows(guideText)) {
            when {
                line.startsWith("<programme ") -> {
                    finish()
                    curChannel = line.substringAfter("channel=\"").substringBefore("\"")
                }
                line.startsWith("<title>") -> curTitle = line.substringAfter('>').substringBefore('<')
                line.startsWith("<desc>") -> curDesc = line.substringAfter('>').substringBefore('<')
                line.startsWith("<category>") || line.startsWith("<genre>") ->
                    curTokens.add(line.substringAfter('>').substringBefore('<'))
                line == "</programme>" -> finish()
            }
        }
        return Parsed(dimensions, cases, corrupt, programmes, guideBytes, files)
    }

    fun countOccurrences(haystack: String, needle: String): Int {
        if (needle.isEmpty()) return 0
        var count = 0
        var at = haystack.indexOf(needle, 0)
        while (at >= 0) {
            count++
            at = haystack.indexOf(needle, at + needle.length)
        }
        return count
    }

    fun privacyHits(text: String): Int {
        var hits = 0
        val needles = arrayOf("://", "password=", "passwd=", "secret=", "apikey=",
            "credential=", "pin=", "bearer ", "authorization:", derivedToken())
        val lower = text.lowercase()
        for (needle in needles) if (lower.contains(needle.lowercase())) hits++
        return hits
    }

    /**
     * Model checks. Returns the number of emitted PASS checks, or -1 on the first FAIL.
     * Structural flags are mode-driven so each mutation reaches its named guard.
     */
    fun verifyModel(mode: String, files: Map<String, ByteArray>, sink: (String) -> Unit): Int {
        var passed = 0
        fun pass(id: String, detail: String) { sink("CHECK\t" + id + "\tPASS\t" + detail); passed++ }
        fun fail(id: String, detail: String): Int {
            sink("CHECK\t" + id + "\tFAIL\t" + detail)
            sink("FIRST\t" + id)
            return -1
        }
        val checkByte = mode == "verify" || mode == "verify-byte"
        val checkManifest = mode == "verify" || mode == "verify-manifest" || mode == "verify-mutant"
        val checkPinned = mode == "verify" || mode == "verify-pinned"

        val generated = generate()
        if (checkByte) {
            var same = generated.size == files.size
            for ((name, bytes) in generated) {
                if (same && !bytes.contentEquals(files[name] ?: ByteArray(0))) same = false
            }
            if (!same) return fail("BYTE_IDENTITY", "regenerated-bytes-differ")
            pass("BYTE_IDENTITY", "files=" + generated.size)
        }

        val headerOk =
            files["cases.tsv"]?.toString(Charsets.UTF_8)?.let {
                rows(it).firstOrNull() == CASE_HEADER
            } == true &&
            files["corrupt.txt"]?.toString(Charsets.UTF_8)?.let {
                rows(it).firstOrNull() == CORRUPT_HEADER
            } == true &&
            files["dimensions.tsv"]?.toString(Charsets.UTF_8)?.let {
                rows(it).firstOrNull() == DIM_HEADER
            } == true
        if (!headerOk) return fail("HEADER_STRICT", "strict-header-mismatch")

        val rawBoundsOk =
            rows(files.getValue("cases.tsv").toString(Charsets.UTF_8)).drop(1).all {
                strictFields(it, 5) != null
            } &&
            rows(files.getValue("corrupt.txt").toString(Charsets.UTF_8)).drop(1).all {
                strictFields(it, 3) != null
            } &&
            rows(files.getValue("dimensions.tsv").toString(Charsets.UTF_8)).drop(1).all {
                strictFields(it, 2) != null
            }
        if (!rawBoundsOk) return fail("ROW_BOUNDS", "row-field-count")

        val parsed = parseFixture(files) ?: return fail("HEADER_STRICT", "fixture-parse-null")

        if (checkManifest) {
            val manifest = files["sha256.txt"]?.toString(Charsets.UTF_8)
                ?: return fail("MANIFEST_CONSISTENT", "manifest-missing")
            var ok = true
            for (line in rows(manifest)) {
                if (line.isEmpty()) continue
                val f = strictFields(line, 2) ?: return fail("MANIFEST_CONSISTENT", "manifest-field-count")
                val bytes = files[f[1]] ?: return fail("MANIFEST_CONSISTENT", "manifest-file-missing")
                if (sha256(bytes) != f[0]) ok = false
            }
            if (!ok) return fail("MANIFEST_CONSISTENT", "manifest-digest-mismatch")
            pass("MANIFEST_CONSISTENT", "files=" + DATA_FILES.size)
        }

        if (checkPinned) {
            val wantGuide = parsed.dimensions["guide_sha256"] ?: return fail("PINNED_DIGEST", "guide-pin-missing")
            if (sha256(parsed.guideBytes) != wantGuide) return fail("PINNED_DIGEST", "guide-digest-drift")
            val tokens = parseProgrammeTokens(parsed.guideBytes.toString(Charsets.UTF_8))
            val admitted = LinkedHashMap<String, ArrayList<String>>()
            for ((channel, canonical) in tokens) admitted.getOrPut(channel) { ArrayList() }.add(canonical)
            val mirror = StringBuilder()
            for ((channel, canonicals) in admitted) {
                mirror.append(channel).append('=')
                canonicals.distinct().sorted().joinTo(mirror, ",")
                mirror.append(';')
            }
            val wantMirror = parsed.dimensions["mirror_digest"] ?: return fail("PINNED_DIGEST", "mirror-pin-missing")
            if (sha256(mirror.toString().toByteArray(Charsets.UTF_8)) != wantMirror)
                return fail("PINNED_DIGEST", "mirror-digest-drift")
            pass("PINNED_DIGEST", "guide-and-mirror-pinned")
        }

        if (parsed.cases.isEmpty()) return fail("HEADER_STRICT", "case-rows-empty")
        if (parsed.corrupt.isEmpty()) return fail("HEADER_STRICT", "corrupt-rows-empty")
        if (parsed.programmes.isEmpty()) return fail("HEADER_STRICT", "programme-rows-empty")
        pass("HEADER_STRICT", "header-and-nonempty-rows")

        var boundsOk = true
        for (c in parsed.cases) {
            if (c.id.length != 3 || c.raw.length > 32 || c.canonical.length > MAX_TOKEN_CHARS) boundsOk = false
        }
        for ((id, value) in parsed.corrupt) {
            if (id.length != 3 || value.second.isEmpty() || value.second.size > 20000) boundsOk = false
        }
        for (p in parsed.programmes) {
            // Four admitted tokens plus one injected unknown fail-closed token.
            if (p.rawTokens.size > MAX_TOKENS_PER_PROGRAMME + 1 || p.title.length > 400) boundsOk = false
        }
        if (!boundsOk) return fail("ROW_BOUNDS", "field-or-payload-bound-exceeded")
        pass("ROW_BOUNDS", "cases=" + parsed.cases.size + ",corrupt=" + parsed.corrupt.size)

        val wantCases = parsed.dimensions["case_count"]?.toIntOrNull() ?: return fail("CAP_BINDING", "case-count-missing")
        val wantChannels = parsed.dimensions["channel_count"]?.toIntOrNull() ?: return fail("CAP_BINDING", "channel-count-missing")
        val wantProgrammes = parsed.dimensions["programme_count"]?.toIntOrNull() ?: return fail("CAP_BINDING", "programme-count-missing")
        val wantCorrupt = parsed.dimensions["corrupt_count"]?.toIntOrNull() ?: return fail("CAP_BINDING", "corrupt-count-missing")
        val wantMaxTokens = parsed.dimensions["max_tokens"]?.toIntOrNull() ?: return fail("CAP_BINDING", "max-tokens-missing")
        val distinctChannels = parsed.programmes.map { it.channel }.distinct().size
        if (parsed.cases.size != wantCases || distinctChannels != wantChannels ||
            parsed.programmes.size != wantProgrammes || parsed.corrupt.size != wantCorrupt ||
            wantMaxTokens != MAX_TOKENS_PER_PROGRAMME) return fail("CAP_BINDING", "pinned-counts-mismatch")
        if (parsed.programmes.none { it.rawTokens.size == MAX_TOKENS_PER_PROGRAMME })
            return fail("CAP_BINDING", "token-cap-not-bound")
        pass("CAP_BINDING", "cases=" + wantCases + ",channels=" + wantChannels + ",programmes=" + wantProgrammes)

        for (c in parsed.cases) {
            val got = normalize(c.raw)
            if (c.decision == "ADMIT") {
                if (got != c.canonical) return fail("TOKEN_NORMALIZATION", c.id + "-canonical-mismatch")
            } else {
                if (got.isNotEmpty()) return fail("TOKEN_NORMALIZATION", c.id + "-not-rejected")
                if (c.code != "REJECT_UNKNOWN" && c.code != "REJECT_EMPTY" &&
                    c.code != "REJECT_LENGTH" && c.code != "REJECT_CONTROL")
                    return fail("TOKEN_NORMALIZATION", c.id + "-unknown-reject-code")
            }
        }
        pass("TOKEN_NORMALIZATION", "cases=" + parsed.cases.size)

        var dedupeOk = true
        var collapsed = 0
        for (p in parsed.programmes) {
            val admitted = p.rawTokens.map { normalize(it) }.filter { it.isNotEmpty() }
            if (admitted.any { it !in REGISTRY_SET }) dedupeOk = false
            if (admitted.size > admitted.distinct().size) collapsed++
            if (p.rawTokens.any { normalize(it).isEmpty() && it.isNotBlank() && it != "UNLISTED" &&
                !it.startsWith("ABCDEFGHIJKLMNOPQ") }) dedupeOk = false
        }
        if (!dedupeOk || collapsed == 0) return fail("TOKEN_DEDUPE",
            "invalid-canonical-or-no-collapse")
        pass("TOKEN_DEDUPE", "programmes=" + parsed.programmes.size + ",collapsed=" + collapsed)

        val canonicalDoctype = "<!DOCTYPE tv SYSTEM \"xmltv.dtd\">"
        var corruptOk = true
        var badCorrupt = ""
        for ((id, value) in parsed.corrupt) {
            val text = value.second.toString(Charsets.UTF_8)
            val ok = when (id) {
                "X01" -> !text.contains("xmltv.dtd\"") || text.contains("other.dtd")
                "X02" -> text.contains("[<!ENTITY")
                "X03" -> !text.contains("<tv>") && text.contains("<guide>")
                "X04" -> countOccurrences(text, "<category>") > countOccurrences(text, "</category>")
                "X05" -> value.second.contains(0xFF.toByte())
                "X06" -> countOccurrences(text, canonicalDoctype) >= 2
                "X07" -> value.second.size > 8192
                "X08" -> countOccurrences(text, "<category>") >= 70
                "X09" -> normalize("ABCDEFGHIJKLMNOPQRSTUVWXY").isEmpty()
                else -> false
            }
            if (!ok) { corruptOk = false; if (badCorrupt.isEmpty()) badCorrupt = id }
        }
        if (!corruptOk) return fail("CORRUPT_FAIL_CLOSED", "corrupt-variant-not-distinct:id=" + badCorrupt)
        pass("CORRUPT_FAIL_CLOSED", "documents=" + parsed.corrupt.size)

        val diagnostics = StringBuilder()
        for (line in rows(files["report-copy.txt"]?.toString(Charsets.UTF_8) ?: "")) diagnostics.append(line).append(NL)
        val hits = privacyHits(diagnostics.toString())
        if (hits != 0) return fail("PRIVACY_SCAN", "sensitive-pattern-hits=" + hits)
        pass("PRIVACY_SCAN", "hits=0")

        return passed
    }

    @JvmStatic
    fun main(args: Array<String>) {
        val sink: (String) -> Unit = { println(it) }
        val generated = generate()
        var passed = 0
        var rc = 0
        try {
            val n = verifyModel("verify", generated, sink)
            if (n < 0) rc = 1 else passed = n
        } catch (t: Throwable) {
            sink("FIRST\tCONTRACT_EXCEPTION")
            sink("EXCEPTION\t" + t.javaClass.simpleName)
            rc = 1
        }
        sink("SUMMARY\tchecks=" + passed + "\tfail=" + if (rc == 0) 0 else 1)
        sink("VERDICT\t" + if (rc == 0) "PASS" else "FAIL")
        System.exit(rc)
    }
}
